contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 t0, uint256 t1) public payable {
        require(address(this).balance >= amount);
        require(amount == 10 ether);
        require(t1 > t0);

        (bool s0, bytes memory d) = address(c).call{value: t0}("");
        require(s0 && d.length == 0);

        uint256 beforeBal = address(c).balance;
        uint256 beforeTime = c.pastBlockTime();

        bool reverted;
        try this._doFallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;
        uint256 afterTime = c.pastBlockTime();

        if (reverted) {
            assert(afterBal == beforeBal && afterTime == beforeTime);
        } else {
            assert(afterTime == block.timestamp && (afterBal == beforeBal || afterBal == 0));
        }
    }

    function _doFallback() external payable {
        require(msg.sender == address(this));
        c.fallback{value: msg.value}();
    }

    receive() external payable {}
}

