contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amountBefore, uint amountCall) public payable {
        require(address(this).balance >= amountBefore + amountCall, "insufficient balance");

        bool setupOk;
        if (amountBefore > 0) {
            try c.call{value: amountBefore}("") {
                setupOk = true;
            } catch {
                setupOk = false;
            }
        } else {
            setupOk = true;
        }

        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        try c.call{value: amountCall}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        if (amountCall != 10 ether) {
            assert(reverted);
        } else if (!reverted) {
            assert(pastAfter > pastBefore);
            assert(pastAfter == block.timestamp);
            assert(setupOk);
            if (block.number % 15 != 0) {
                assert(balAfter == balBefore + 10 ether);
            }
        } else {
            assert(setupOk);
            assert(balAfter == balBefore);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

