contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 newTime) public payable {
        require(address(this).balance >= amount);

        uint256 oldTime = c.pastBlockTime();

        // Establish a known pastBlockTime: an initial successful call requires
        // block.timestamp > 0, which is always true on a real chain, so send
        // exactly 10 ether and expect success.
        c.fallback{value: 10 ether}();
        uint256 storedTime = c.pastBlockTime();
        require(storedTime > oldTime);

        // The deciding call uses a caller-provided amount; only amount == 10 ether
        // can possibly succeed according to the contract's value requirement.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (amount != 10 ether || block.timestamp <= storedTime));
    }

    receive() external payable {}
}

