contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint preTime, uint preBal) public payable {
        // Need enough balance to send exactly 10 ether.
        require(address(this).balance >= 10 ether);

        // First call: may succeed or fail depending on initial timestamp, but sets pastBlockTime on success.
        // Send exactly 10 ether; this is a top-level state-changing call.
        try c.fallback{value: 10 ether}() { } catch { }

        // Read current observable state before the deciding call.
        preTime = c.pastBlockTime();
        preBal = address(c).balance;

        // Second call: decide based on previous pastBlockTime and block.timestamp.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // If the call reverted, timestamp was not greater than the stored pastBlockTime,
            // and the stored time is unchanged.
            assert(block.timestamp <= preTime);
            assert(c.pastBlockTime() == preTime);
        } else {
            // If the call succeeded, timestamp was greater than preTime,
            // and pastBlockTime was updated to block.timestamp.
            assert(block.timestamp > preTime);
            assert(c.pastBlockTime() == block.timestamp);
            // The contract may have transferred its balance if block.number % 15 == 0.
            // Its balance is exactly preBal + 10 ether if no transfer occurred, or 0 if it transferred everything.
            assert(address(c).balance == preBal + 10 ether || address(c).balance == 0);
        }
    }

    receive() external payable { }
}

