    }

    function run(uint amount, uint newTimestamp, uint newNumber) public payable {
        require(address(this).balance >= amount, "not enough balance");

        // Setup: make c's pastBlockTime a known baseline, if the input timestamp allows it.
        // The baseline call must be valid for the current compiler block timestamp.
        uint beforePastBlockTime = c.pastBlockTime();
        bool setupReverted;
        if (amount == 10 ether && newTimestamp > beforePastBlockTime) {
            try c.fallback{value: amount}() {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
        } else {
            setupReverted = true;
        }

        // Re-read observable state after setup; this is still a read-only call.
        uint pastBefore = c.pastBlockTime();
        uint cBalanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        // The deciding call: this test must be able to control its arguments.
        // We cannot choose the real block.timestamp/number, so we only exercise the
        // value-based and pastBlockTime-based conditions that are observable now.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        assert(
            reverted == (amount != 10 ether || newTimestamp <= pastBefore)
        );

        assert(
            reverted || pastAfter == block.timestamp
        );

        assert(
            reverted || (block.number % 15 != 0) || myBalanceAfter == myBalanceBefore + cBalanceBefore
        );

        assert(
            reverted || (block.number % 15 != 0) || cBalanceAfter == 0
        );
    }

    receive() external payable {}
}

