contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint initialTime) public payable {
        require(address(this).balance >= amount);

        // Set pastBlockTime to initialTime by first sending exactly 10 ether and
        // convincing block.timestamp > pastBlockTime. If this setup call reverts,
        // we cannot reach the deciding call, so require it to succeed.
        (bool setupOk,) = address(c).call{value: 10 ether}("");
        require(setupOk);

        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // General rule: exactly 10 ether is required, and the timestamp must
        // strictly increase. If the call succeeds, the recorded timestamp is
        // updated to the current block timestamp and any balance change can only
        // be the total contract balance moving out when block.number % 15 == 0.
        if (amount != 10 ether || block.timestamp == pastBefore) {
            assert(reverted && pastAfter == pastBefore && balAfter == balBefore);
        } else {
            assert(!reverted && pastAfter == block.timestamp);
            if (block.number % 15 == 0) {
                assert(balAfter == 0);
            } else {
                assert(balAfter == balBefore + amount);
            }
        }
    }

    receive() external payable {}
}

