                // Since the setup call already succeeded, the contract received setupValue earlier,
                // so balAfter should equal balBefore + amount in that branch.
                assert(balAfter == balBefore + amount);
            }
        } else {
            assert(pastAfter == pastBefore && balAfter == balBefore);
        }
    }

