        assert(reverted == (ethAmount != 10 ether || block.timestamp <= before));
        assert(reverted || c.pastBlockTime() == block.timestamp);
        assert(!reverted || c.pastBlockTime() == before);
    }

    receive() external payable {}
}

contract InvMutTest {
